<script setup>
import {ref,onMounted,onUnmounted} from 'vue'
import {Mic,Database,ArrowUpRight,Link,Server} from 'lucide-vue-next'
import {rpc} from '../transport'
import {state,notice} from '../state'
let timer
async function load(){try{state.models=(await rpc('bootstrap')).rows||[]}catch(e){notice(e.message)}}
onMounted(()=>{load();timer=setInterval(load,5000)});onUnmounted(()=>clearInterval(timer))
</script>
<template><div><div class="compact-intro"><div><div class="eyebrow">VERWALTUNG</div><h1>Einstellungen</h1><p>Stimmen, Antwortcache und Modellstatus.</p></div><span class="tag">Lokale Demo · Administrator</span></div><div class="admin-grid"><RouterLink to="/admin/voices" class="admin-tile"><span class="feature-icon teal"><Mic :size="26"/></span><ArrowUpRight class="feature-arrow" :size="20"/><h2>Stimmen</h2><p>Eigene Aufnahmen sammeln, Piper trainieren und die Antwortstimme auswählen.</p></RouterLink><RouterLink to="/admin/cache" class="admin-tile"><span class="feature-icon blue"><Database :size="26"/></span><ArrowUpRight class="feature-arrow" :size="20"/><h2>Antwortcache</h2><p>Vorbereitete Audiodateien, neue Antwortvarianten und Hintergrundaufträge.</p></RouterLink></div><div class="panel model-panel"><div class="panel-heading"><h2>Lokale CPU-Modelle</h2><Server :size="20"/></div><div v-for="m in state.models" :key="m.id" class="model-row"><strong>{{{laya:'Laya · Klassifikation',piper:'Piper · Sprachausgabe',whisper:'Whisper Tiny · Spracherkennung',qwen:'Qwen 3.5 · Antwortvarianten'}[m.title]||m.title}}</strong><span class="model-status" :class="{ready:m.state==='ready'}">{{m.state==='ready'?'Bereit':m.state==='loading'?'Wird geladen':m.state==='not_loaded'?'Noch nicht geladen':m.state==='working'?'Erzeugt eine Variante':m.state}}</span></div></div><div class="integration-note"><Link :size="20"/><div><strong>Benutzerverwaltung und Berechtigungen</strong><p>Diese lokal gebundene Demo verwendet eine feste Demoidentität. Es werden hier keine Mitarbeiter angelegt. Eine produktive Firmenanmeldung ist noch nicht konfiguriert.</p></div></div></div></template>
